void status_req_obdcan_check (void)
{
    #if STATUS_DTC_ENABLE == 1
      static Boolean obd_can_check_done = FALSE ;

	  status_req_vars.obd_can_check_ena = TRUE ;

      if(!obd_can_is_active() && status_req_vars.smartstart_is_connect && !obd_can_check_done)
        {
          Display_Type obd_not_active[] = {RED_LED, RED_LED, BOTH_LED} ;
          display_pattern(obd_not_active, DISPLAY_300MS_FLASH, 3, 10)  ;
          
          obd_can_check_done = TRUE ; 
        }

    #endif     
}

